library(shiny)

## ---------------------------------------------------------------- objectives
mk &lt;- function(label, fv, xlim, ylim, start, xstar) {
  force(fv)
  list(label = label, fv = fv, f = function(p) fv(p[1], p[2]),
       xlim = xlim, ylim = ylim, start = start,
       xstar = matrix(xstar, ncol = 2))
}

FNS &lt;- list(
  quad = mk(
    "(a) Well-conditioned quadratic",
    function(x, y) 0.5 * (2 * (x - 1)^2 + 1.6 * (x - 1) * (y - 1) +
                          2 * (y - 1)^2),
    c(-3, 4), c(-3, 4), c(-2, 3), c(1, 1)
  ),
  banana = mk(
    "(b) Rosenbrock banana (narrow curved ridge)",
    function(x, y) (1 - x)^2 + 100 * (y - x^2)^2,
    c(-2, 2), c(-1, 3), c(-1.2, 1), c(1, 1)
  ),
  mix = mk(
    "(c) Highly correlated, two modes",
    function(x, y) {
      rho &lt;- 0.9; den &lt;- 1 - rho^2
      q &lt;- function(u, v) (u^2 - 2 * rho * u * v + v^2) / den
      -log(exp(-0.5 * q(x - 1.2, y - 1.2)) +
           0.6 * exp(-0.5 * q(x + 1.5, y + 1.5) / 1.5) + 1e-12)
    },
    c(-4, 4), c(-4, 4), c(-3, -0.5), c(1.2, 1.2)
  ),
  himmel = mk(
    "(d) Himmelblau (four global minima)",
    function(x, y) (x^2 + y - 11)^2 + (x + y^2 - 7)^2,
    c(-5, 5), c(-5, 5), c(-4, 4),
    rbind(c(3, 2), c(-2.805118, 3.131312),
          c(-3.779310, -3.283186), c(3.584428, -1.848126))
  ),
  beale = mk(
    "(e) Beale (flat plateau, sharp valley)",
    function(x, y) (1.5 - x + x * y)^2 + (2.25 - x + x * y^2)^2 +
                   (2.625 - x + x * y^3)^2,
    c(-4.5, 4.5), c(-4.5, 4.5), c(-1, 1), c(3, 0.5)
  ),
  rastrigin = mk(
    "(f) Rastrigin (many local minima)",
    function(x, y) 20 + x^2 - 10 * cos(2 * pi * x) +
                        y^2 - 10 * cos(2 * pi * y),
    c(-5.12, 5.12), c(-5.12, 5.12), c(-3.1, 4.2), c(0, 0)
  )
)

## ------------------------------------------------- numerical derivatives
num_grad &lt;- function(f, x) {
  h &lt;- 1e-5 * (1 + abs(x))
  g &lt;- numeric(2)
  for (i in 1:2) {
    e &lt;- numeric(2); e[i] &lt;- h[i]
    g[i] &lt;- (f(x + e) - f(x - e)) / (2 * h[i])
  }
  g
}

num_hess &lt;- function(f, x) {
  h &lt;- 1e-4 * (1 + abs(x))
  H &lt;- matrix(0, 2, 2)
  for (i in 1:2) for (j in i:2) {
    ei &lt;- numeric(2); ei[i] &lt;- h[i]
    ej &lt;- numeric(2); ej[j] &lt;- h[j]
    H[i, j] &lt;- (f(x + ei + ej) - f(x + ei - ej) -
                f(x - ei + ej) + f(x - ei - ej)) / (4 * h[i] * h[j])
    H[j, i] &lt;- H[i, j]
  }
  H
}

## --------------------------------------------------- Wolfe line search
line_search &lt;- function(f, g, x, d, a0 = 1, c1 = 1e-4, c2 = 0.9) {
  f0 &lt;- f(x); gd0 &lt;- sum(g * d)
  if (!is.finite(gd0) || gd0 &gt;= 0) return(list(alpha = 0, ok = FALSE))
  lo &lt;- 0; hi &lt;- Inf; a &lt;- a0
  for (it in 1:60) {
    fa &lt;- f(x + a * d)
    if (!is.finite(fa) || fa &gt; f0 + c1 * a * gd0) {
      hi &lt;- a; a &lt;- 0.5 * (lo + hi)
    } else {
      ga &lt;- num_grad(f, x + a * d)
      if (sum(ga * d) &lt; c2 * gd0) {
        lo &lt;- a
        a &lt;- if (is.finite(hi)) 0.5 * (lo + hi) else min(2 * a, 1e4)
      } else {
        return(list(alpha = a, ok = TRUE))
      }
    }
    if (a &lt; 1e-14) return(list(alpha = 0, ok = FALSE))
  }
  list(alpha = a, ok = (a &gt; 0))
}

## ------------------------------------------------------------- algorithms
run_alg &lt;- function(alg, FN, x0, maxit = 60, tol = 1e-6) {
  f &lt;- FN$f
  X &lt;- matrix(NA_real_, maxit + 1, 2); G &lt;- matrix(NA_real_, maxit + 1, 2)
  D &lt;- matrix(NA_real_, maxit + 1, 2); Fv &lt;- rep(NA_real_, maxit + 1)
  AL &lt;- rep(NA_real_, maxit + 1)
  x &lt;- x0; B &lt;- diag(2)
  g_prev &lt;- NULL; d_prev &lt;- NULL; s_prev &lt;- NULL
  n &lt;- 0; note &lt;- "maximum number of iterations reached"

  for (k in seq_len(maxit)) {
    g &lt;- num_grad(f, x); gn &lt;- sqrt(sum(g^2))
    X[k, ] &lt;- x; G[k, ] &lt;- g; Fv[k] &lt;- f(x); n &lt;- k
    if (!is.finite(gn)) { note &lt;- "diverged"; break }
    if (gn &lt; tol) { note &lt;- "converged (||grad|| &lt; 1e-6)"; break }

    if (alg == "nr") {
      H &lt;- num_hess(f, x); H &lt;- (H + t(H)) / 2
      ev &lt;- eigen(H, symmetric = TRUE, only.values = TRUE)$values
      delta &lt;- 1e-3 * max(1, max(abs(ev)))
      tau &lt;- max(0, delta - min(ev))
      d &lt;- tryCatch(solve(H + tau * diag(2), -g), error = function(e) -g)
    } else if (alg == "gd") {
      d &lt;- -g
    } else if (alg == "cg") {
      if (is.null(d_prev)) {
        d &lt;- -g
      } else {
        y &lt;- g - g_prev
        beta &lt;- max(0, sum(g * y) / max(sum(g_prev^2), 1e-300))   # PR+
        d &lt;- -g + beta * d_prev
      }
      if (sum(g * d) &gt; -1e-12) d &lt;- -g                            # restart
    } else {                                                      # BFGS
      if (!is.null(s_prev)) {
        y &lt;- g - g_prev; sy &lt;- sum(s_prev * y)
        if (sy &gt; 1e-10) {
          rho &lt;- 1 / sy
          V &lt;- diag(2) - rho * outer(s_prev, y)
          B &lt;- V %*% B %*% t(V) + rho * outer(s_prev, s_prev)
        }
      }
      d &lt;- -as.vector(B %*% g)
      if (sum(g * d) &gt; -1e-12) { B &lt;- diag(2); d &lt;- -g }
    }

    ls &lt;- line_search(f, g, x, d)
    D[k, ] &lt;- d; AL[k] &lt;- ls$alpha
    if (ls$alpha &lt;= 0) { note &lt;- "line search failed (flat or non-descent)"; break }

    s_prev &lt;- ls$alpha * d; g_prev &lt;- g; d_prev &lt;- d
    x &lt;- x + s_prev
  }

  list(X = X[1:n, , drop = FALSE], G = G[1:n, , drop = FALSE],
       D = D[1:n, , drop = FALSE], F = Fv[1:n], A = AL[1:n],
       n = n, note = note)
}

ALGS &lt;- c("Safeguarded Newton (modified Hessian + line search)" = "nr",
          "Gradient descent + line search"    = "gd",
          "Conjugate gradient (PR+)"          = "cg",
          "BFGS (quasi-Newton)"               = "bfgs")

## ---------------------------- widen the data box to the device aspect ratio
expand_box &lt;- function(xlim, ylim, pin) {
  if (length(pin) != 2 || any(!is.finite(pin)) || any(pin &lt;= 0))
    return(list(xlim = xlim, ylim = ylim))
  r &lt;- pin[1] / pin[2]
  wd &lt;- diff(xlim); ht &lt;- diff(ylim)
  if (wd / ht &lt; r) {
    w &lt;- ht * r; m &lt;- mean(xlim); xlim &lt;- m + c(-0.5, 0.5) * w
  } else {
    h &lt;- wd / r; m &lt;- mean(ylim); ylim &lt;- m + c(-0.5, 0.5) * h
  }
  list(xlim = xlim, ylim = ylim)
}

## --------------------------------------------------------------------- UI
## an icon-only playback button; the title shows as a tooltip
ctrl_btn &lt;- function(id, icon_name, title, class = "btn-default")
  actionButton(id, NULL, icon = icon(icon_name), title = title, class = class,
               style = "flex: 1; padding: 6px 0;")

ui &lt;- fluidPage(
  titlePanel("Shinylive App for Comparing the Optimizers"),
  sidebarLayout(
    sidebarPanel(
      width = 4,
      selectInput("fn", "objective function",
                  setNames(names(FNS), sapply(FNS, `[[`, "label"))),
      selectInput("alg", "algorithm", ALGS),
      div(style = "display: flex; gap: 10px;",
          div(style = "flex: 1;",
              numericInput("x1", HTML("starting x&lt;sub&gt;1&lt;/sub&gt;"),
                           value = FNS[[1]]$start[1], step = 0.5,
                           width = "100%")),
          div(style = "flex: 1;",
              numericInput("x2", HTML("starting x&lt;sub&gt;2&lt;/sub&gt;"),
                           value = FNS[[1]]$start[2], step = 0.5,
                           width = "100%"))),
      helpText("Or click inside the contour plot to choose a new ",
               "starting value."),
      selectInput("compare", "overlay the path of",
                  c("none" = "none", ALGS)),
      checkboxInput("autoplay", "autoplay when the start changes", TRUE),
      sliderInput("k", "iteration", min = 0, max = 1, value = 0, step = 1),
      div(style = "display: flex; gap: 4px;",
          ctrl_btn("first", "backward-fast", "Back to the start"),
          ctrl_btn("back",  "backward-step", "One step back"),
          ctrl_btn("play",  "play",          "Play", class = "btn-primary"),
          ctrl_btn("pause", "pause",         "Pause"),
          ctrl_btn("step",  "forward-step",  "One step forward"),
          ctrl_btn("toend", "forward-fast",  "To the end")),
      hr(),
      helpText("Try gradient descent on the Rosenbrock banana, overlaid ",
               "with BFGS or safeguarded Newton: gradient descent zig-zags ",
               "across the curved valley, while the curvature-aware methods ",
               "follow it. On Himmelblau and Rastrigin, click different ",
               "starting points to see which minimum each method finds.")
    ),
    mainPanel(
      width = 8,
      plotOutput("contour", click = "click", height = "500px"),
      ## details of the iterations, shown under the plot
      hr(),
      div(style = "max-width: 560px;",
          tableOutput("tab"),
          htmlOutput("note"))
    )
  )
)

## ----------------------------------------------------------------- server
server &lt;- function(input, output, session) {

  FN &lt;- reactive(FNS[[input$fn]])
  playing &lt;- reactiveVal(FALSE)
  play_ms &lt;- 900

  set_start &lt;- function(p) {
    updateNumericInput(session, "x1", value = round(p[1], 2))
    updateNumericInput(session, "x2", value = round(p[2], 2))
  }

  ## a new objective moves the start to its default; clicking the contour
  ## plot moves it to the clicked point
  observeEvent(input$fn, set_start(FNS[[input$fn]]$start), ignoreInit = TRUE)
  observeEvent(input$click, {
    p &lt;- c(input$click$x, input$click$y)
    if (all(is.finite(p))) set_start(p)
  })

  start &lt;- reactive({
    req(is.finite(input$x1), is.finite(input$x2))
    c(input$x1, input$x2)
  })

  path &lt;- reactive(run_alg(input$alg, FN(), start()))

  ## a second algorithm from the same start, shown for comparison
  ref &lt;- reactive({
    if (input$compare == "none" || input$compare == input$alg) return(NULL)
    run_alg(input$compare, FN(), start())
  })

  ## current iteration, clamped to the length of the path
  k &lt;- reactive(min(as.integer(input$k), path()$n - 1))

  ## a new path restarts the display at iteration 0
  observeEvent(path(), {
    updateSliderInput(session, "k", max = max(1, path()$n - 1), value = 0)
    playing(isTRUE(input$autoplay) && path()$n &gt; 1)
  })

  go_to &lt;- function(i) {
    updateSliderInput(session, "k", value = max(0, min(i, path()$n - 1)))
  }

  observeEvent(input$play, {
    if (k() &gt;= path()$n - 1) go_to(0)
    if (path()$n &gt; 1) playing(TRUE)
  })
  observeEvent(input$pause, playing(FALSE))
  observeEvent(input$step,  { playing(FALSE); go_to(k() + 1) })
  observeEvent(input$back,  { playing(FALSE); go_to(k() - 1) })
  observeEvent(input$first, { playing(FALSE); go_to(0) })
  observeEvent(input$toend, { playing(FALSE); go_to(path()$n - 1) })

  observe({
    if (!isTRUE(playing())) return()
    kk &lt;- isolate(k())
    if (kk &gt;= isolate(path()$n) - 1) { playing(FALSE); return() }
    invalidateLater(play_ms, session)
    isolate(go_to(kk + 1))
  })

  output$contour &lt;- renderPlot({
    FNc &lt;- FN(); P &lt;- path(); RP &lt;- ref(); kk &lt;- k() + 1L

    par(mar = c(7, 4, 2, 1))                 # room for the legend below
    plot.new()
    bx &lt;- expand_box(FNc$xlim, FNc$ylim, par("pin"))
    plot.window(xlim = bx$xlim, ylim = bx$ylim, xaxs = "i", yaxs = "i")

    xs &lt;- seq(bx$xlim[1], bx$xlim[2], length.out = 180)
    ys &lt;- seq(bx$ylim[1], bx$ylim[2], length.out = 180)
    z  &lt;- outer(xs, ys, FNc$fv)
    zf &lt;- z[is.finite(z)]
    lv &lt;- unique(quantile(zf, probs = seq(0, 1, length.out = 30)^1.7))
    contour(xs, ys, z, levels = lv, add = TRUE, col = "grey70",
            drawlabels = FALSE)
    axis(1); axis(2); box()
    title(main = paste0(names(ALGS)[ALGS == input$alg], " on ",
                        sub("^\\([a-f]\\) ", "", FNc$label)),
          xlab = expression(x[1]), ylab = expression(x[2]), cex.main = 1)
    points(FNc$xstar[, 1], FNc$xstar[, 2], pch = 3, col = "darkgreen",
           lwd = 2, cex = 1.2)

    ## the comparison path, drawn underneath
    if (!is.null(RP)) {
      Q &lt;- RP$X[seq_len(min(kk, RP$n)), , drop = FALSE]
      if (nrow(Q) &gt; 1) lines(Q[, 1], Q[, 2], col = "grey45", lwd = 2, lty = 2)
      points(Q[, 1], Q[, 2], pch = 21, bg = "grey85", col = "grey45",
             cex = 0.9)
    }

    X &lt;- P$X
    if (kk &gt; 1) lines(X[1:kk, 1], X[1:kk, 2], col = "steelblue", lwd = 2)
    points(X[1:kk, 1], X[1:kk, 2], pch = 21, bg = "steelblue", cex = 1.1)

    cur &lt;- X[kk, ]
    inside &lt;- cur[1] &gt;= bx$xlim[1] && cur[1] &lt;= bx$xlim[2] &&
              cur[2] &gt;= bx$ylim[1] && cur[2] &lt;= bx$ylim[2]
    if (inside) {
      ## Arrow along -grad f (steepest descent), of fixed length on screen.
      ## The gradient is a covector, so its on-screen components are obtained
      ## by multiplying by the units-per-inch factors; the box is widened to
      ## the device aspect ratio, so here the two factors agree anyway.
      g &lt;- -P$G[kk, ]
      upi &lt;- c(diff(par("usr")[1:2]) / par("pin")[1],
               diff(par("usr")[3:4]) / par("pin")[2])
      gs &lt;- g * upi
      if (sqrt(sum(g^2)) &gt; 1e-6 && sqrt(sum(gs^2)) &gt; 0) {
        d &lt;- 0.45 * gs / sqrt(sum(gs^2)) * upi              # 0.45 inch long
        arrows(cur[1], cur[2], cur[1] + d[1], cur[2] + d[2],
               col = "#E8820C", lwd = 3, length = 0.09)
      }
      points(cur[1], cur[2], pch = 21, bg = "firebrick", cex = 1.8)
    } else {
      mtext(sprintf("current iterate (%.3g, %.3g) is off the plotted region",
                    cur[1], cur[2]), side = 3, line = -1.5,
            col = "firebrick", cex = 0.9)
    }

    leg &lt;- list(txt = c("current iterate", "minimum",
                        "steepest descent (direction)"),
                pch = c(21, 3, NA), bg = c("firebrick", NA, NA),
                lwd = c(NA, 2, 3), lty = c(NA, NA, 1),
                col = c("black", "darkgreen", "#E8820C"))
    if (!is.null(RP)) {
      leg$txt &lt;- c(leg$txt, names(ALGS)[ALGS == input$compare])
      leg$pch &lt;- c(leg$pch, NA); leg$bg &lt;- c(leg$bg, NA)
      leg$lwd &lt;- c(leg$lwd, 2);  leg$lty &lt;- c(leg$lty, 2)
      leg$col &lt;- c(leg$col, "grey45")
    }
    ## legend under the x axis label, so that it never covers the path
    y0 &lt;- grconvertY(grconvertY(par("usr")[3], "user", "inches") -
                     3.2 * par("csi"), "inches", "user")
    legend(mean(par("usr")[1:2]), y0, xjust = 0.5, yjust = 1, xpd = NA,
           ncol = 2, bty = "n", cex = 0.85,
           pch = leg$pch, pt.bg = leg$bg, lwd = leg$lwd, lty = leg$lty,
           col = leg$col, legend = leg$txt)
  })

  ## compact numbers: fixed with three decimals, switching to scientific
  ## for very large or very small values
  f3 &lt;- function(x) ifelse(!is.finite(x), "",
          ifelse(abs(x) &gt;= 1e5 | (x != 0 & abs(x) &lt; 1e-3),
                 formatC(x, format = "e", digits = 1),
                 formatC(x, format = "f", digits = 3)))

  ## why the run ended, shown as one line under the table
  output$note &lt;- renderUI({
    P &lt;- path(); RP &lt;- ref()
    if (k() + 1 &lt; P$n) return(NULL)
    HTML(paste0("&lt;i&gt;", P$note,
                if (!is.null(RP)) paste0("; ", names(ALGS)[ALGS == input$compare],
                                         ": ", RP$note, " after ", RP$n - 1,
                                         " iterations"),
                "&lt;/i&gt;"))
  })

  output$tab &lt;- renderTable({
    P &lt;- path(); kk &lt;- k() + 1L
    ## the step length that led to each iterate (none for the start)
    a_in &lt;- c(NA, P$A)[seq_len(P$n)]
    i &lt;- seq_len(kk)
    d &lt;- data.frame(iteration = as.character(i - 1),
                    x1 = f3(P$X[i, 1]), x2 = f3(P$X[i, 2]),
                    f = f3(P$F[i]),
                    `||grad||` = f3(sqrt(rowSums(P$G[i, , drop = FALSE]^2))),
                    step = f3(a_in[i]),
                    check.names = FALSE, stringsAsFactors = FALSE)
    tail(d, 5)
  }, rownames = FALSE, align = "r", width = "100%")
}

